* {
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.5;
    color: var(--text-color);
    background-color: var(--bg-color);
    margin: 0;
    padding: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: white;
    padding: 8px;
    z-index: 100;
    text-decoration: none;
}

.skip-link:focus {
    top: 0;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

h1 {
    font-size: 2.25rem;
    font-weight: 800;
    text-align: center;
    margin-bottom: 0.5rem;
}

.intro {
    text-align: center;
    color: #6b7280;
    margin-bottom: 3rem;
    font-size: 1.125rem;
}

.faq-list {
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
}

.example {
    border-bottom: 1px solid var(--border-color);
}

.example:last-child {
    border-bottom: none;
}

h3 {
    margin: 0;
}

.faq-toggle {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1.5rem;
    background: none;
    border: none;
    font-size: 1.125rem;
    font-weight: 600;
    text-align: left;
    color: var(--text-color);
    cursor: pointer;
    transition: background-color 0.2s;
}

.faq-toggle:hover {
    background-color: var(--hover-bg);
}

.faq-toggle:focus {
    outline: 2px solid var(--focus-ring);
    outline-offset: -2px;
}

.faq-toggle .icon::after {
    content: '+';
    font-size: 1.5rem;
    color: #9ca3af;
}

.faq-toggle[aria-expanded="true"] .icon::after {
    content: '−';
}

.details {
    padding: 0 1.5rem 1.5rem;
    color: #4b5563;
}

.details[hidden] {
    display: none;
}

footer {
    text-align: center;
    font-size: 0.875rem;
    color: #9ca3af;
    margin-top: 2rem;
}

@media (forced-colors: active) {
    .faq-toggle:focus {
        outline: 2px solid ButtonText;
    }
}
